def decode_name(data, offset):
    labels = []
    jumped = False
    end_offset = offset
    while True:
        length = data[offset]
        if length & 0xC0 == 0xC0:
            ptr = ((length & 0x3F) << 8) | data[offset + 1]
            if not jumped:
                end_offset = offset + 2
            offset = ptr
            jumped = True
            continue
        if length == 0:
            offset += 1
            if not jumped:
                end_offset = offset
            break
        offset += 1
        labels.append(data[offset:offset+length].decode('ascii'))
        offset += length
    return '.'.join(labels) + '.', end_offset

def encode_name(name):
    out = bytearray()
    if name == '.':
        return b'\x00'
    labels = name.rstrip('.').split('.')
    for label in labels:
        b = label.encode('ascii')
        out.append(len(b))
        out.extend(b)
    out.append(0)
    return bytes(out)

def encode_rdata(rtype, value):
    if rtype == 1:
        return socket.inet_aton(value)
    if rtype == 28:
        return socket.inet_pton(socket.AF_INET6, value)
    if rtype in (2, 5):
        return encode_name(value)
    if rtype == 15:
        pref, host = value
        return struct.pack('!H', pref) + encode_name(host)
    if rtype == 16:
        parts = []
        for item in value:
            if len(item) > 255:
                raise ValueError('TXT too long')
            parts.append(bytes([len(item)]) + item)
        return b''.join(parts)
    raise ValueError(f'unsupported rtype {rtype}')

def encode_rr(name, rtype, ttl, value):
    rdata = encode_rdata(rtype, value)
    return encode_name(name) + struct.pack('!HHIH', rtype, 1, ttl, len(rdata)) + rdata

def build_response(query):
    txid, flags, qdcount, ancount, nscount, arcount = struct.unpack('!HHHHHH', query[:12])
    offset = 12
    questions = []
    qbytes = bytearray()
    for _ in range(qdcount):
        qname, noff = decode_name(query, offset)
        qtype, qclass = struct.unpack('!HH', query[noff:noff+4])
        qpart = query[offset:noff+4]
        qbytes.extend(qpart)
        questions.append((qname, qtype, qclass))
        offset = noff + 4
    qname, qtype, _ = questions[0]
    spec = RESPONSES.get((qname.lower(), qtype), DEFAULT)
    if spec['delay']:
        time.sleep(spec['delay'])
    ans = b''.join(encode_rr(*rr) for rr in spec['answers'])
    auth = b''.join(encode_rr(*rr) for rr in spec['authority'])
    add = b''.join(encode_rr(*rr) for rr in spec['additional'])
    hdr = struct.pack('!HHHHHH', txid, spec['flags'] | (flags & 0x0100), qdcount, len(spec['answers']), len(spec['authority']), len(spec['additional']))
    return hdr + bytes(qbytes) + ans + auth + add, questions, spec

def udp_server():
    s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    s.bind(('127.0.0.1', 5300))
    print('udp ready 127.0.0.1:5300', flush=True)
    while True:
        data, addr = s.recvfrom(4096)
        resp, questions, spec = build_response(data)
        print('udp', addr, questions, flush=True)
        s.sendto(resp, addr)

def tcp_server():
    s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    s.bind(('127.0.0.1', 5300))
    s.listen(5)
    print('tcp ready 127.0.0.1:5300', flush=True)
    while True:
        conn, addr = s.accept()
        threading.Thread(target=handle_tcp, args=(conn, addr), daemon=True).start()

def handle_tcp(conn, addr):
    with conn:
        hdr = conn.recv(2)
        if len(hdr) < 2:
            return
        length = struct.unpack('!H', hdr)[0]
        data = b''
        while len(data) < length:
            chunk = conn.recv(length - len(data))
            if not chunk:
                return
            data += chunk
        resp, questions, spec = build_response(data)
        print('tcp', addr, questions, flush=True)
        conn.sendall(struct.pack('!H', len(resp)) + resp)

threading.Thread(target=udp_server, daemon=True).start()
